#!/usr/bin/env node
// Generates src/generated/{types,operations}.ts from the Handles API OpenAPI spec.
//
//   node scripts/generate.mjs [path-or-url-to-openapi.json]
//
// The default source is the public spec repository. Run it again whenever the spec changes;
// the generated files are committed so that installing the client needs no build step.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const DEFAULT_SPEC = "https://raw.githubusercontent.com/handlesapi/openapi/main/openapi.json";
const here = dirname(fileURLToPath(import.meta.url));
const outDir = resolve(here, "../src/generated");

const source = process.argv[2] ?? DEFAULT_SPEC;
const spec = JSON.parse(
  /^https?:/.test(source) ? await (await fetch(source)).text() : readFileSync(source, "utf8"),
);

const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const key = (k) => (IDENT.test(k) ? k : JSON.stringify(k));
const pascal = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const methodName = (operationId) =>
  operationId
    .split(/[.\-_]/)
    .filter(Boolean)
    .map((part, i) => (i === 0 ? part.charAt(0).toLowerCase() + part.slice(1) : pascal(part)))
    .join("");

function doc(text, indent = "") {
  const t = String(text ?? "").split(/\n\s*\n/)[0].replace(/\s+/g, " ").replace(/\*\//g, "*\\/").trim();
  if (!t) return "";
  const cut = t.length > 220 ? t.slice(0, 217).replace(/\s+\S*$/, "") + "..." : t;
  return `${indent}/** ${cut} */\n`;
}

const isNullable = (s) => (Array.isArray(s?.type) && s.type.includes("null")) || s?.nullable === true;

/** JSON Schema to a TypeScript type expression. Optional properties are `?: T | null`: the API reports "not measured" as null. */
function ts(schema, indent = "") {
  if (!schema) return "unknown";
  if (schema.$ref) return schema.$ref.split("/").pop();
  if (schema.enum) return schema.enum.map((v) => JSON.stringify(v)).join(" | ");
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  const nullable = types.includes("null") || schema.nullable === true;
  const t = types.find((x) => x && x !== "null");
  let base;
  switch (t) {
    case "string":
      base = "string";
      break;
    case "integer":
    case "number":
      base = "number";
      break;
    case "boolean":
      base = "boolean";
      break;
    case "array":
      base = `Array<${ts(schema.items, indent)}>`;
      break;
    case "object":
    case undefined: {
      if (schema.properties) {
        const req = new Set(schema.required ?? []);
        const inner = indent + "  ";
        const lines = Object.entries(schema.properties).map(([name, sub]) => {
          const optional = !req.has(name);
          const type = ts(sub, inner);
          const needsNull = optional && !isNullable(sub) && type !== "unknown";
          return `${doc(sub.description, inner)}${inner}${key(name)}${optional ? "?" : ""}: ${type}${needsNull ? " | null" : ""};`;
        });
        base = `{\n${lines.join("\n")}\n${indent}}`;
      } else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
        base = `Record<string, ${ts(schema.additionalProperties, indent)}>`;
      } else {
        base = t === "object" ? "Record<string, unknown>" : "unknown";
      }
      break;
    }
    default:
      base = "unknown";
  }
  return nullable ? `${base} | null` : base;
}

const header = `// Generated by scripts/generate.mjs from the Handles API OpenAPI spec (v${spec.info.version}). Do not edit by hand.\n`;

// ---- types.ts ----
let types = header + "/* eslint-disable */\n\n";
for (const [name, schema] of Object.entries(spec.components?.schemas ?? {})) {
  if (name === "ApiErrorCode") {
    types += `${doc(schema.description)}export type ApiErrorCode = ${schema.enum.map((v) => JSON.stringify(v)).join(" | ")};\n\n`;
  } else if (name === "ApiError") {
    continue; // hand-written as a class in src/errors.ts
  } else {
    types += `${doc(schema.description)}export type ${name} = ${ts(schema)};\n\n`;
  }
}

const ops = [];
for (const [path, item] of Object.entries(spec.paths)) {
  for (const method of ["get", "post", "put", "patch", "delete"]) {
    const op = item[method];
    if (!op) continue;
    const name = methodName(op.operationId);
    const P = pascal(name);
    const pathParams = [];
    const queryParams = [];
    const bodyParams = [];
    const fields = [];
    for (const p of op.parameters ?? []) {
      (p.in === "path" ? pathParams : queryParams).push(p.name);
      const d = String(p.description ?? "").split(/\n\s*\n/)[0];
      fields.push(`${doc(d, "  ")}  ${key(p.name)}${p.required ? "" : "?"}: ${ts(p.schema, "  ")};`);
    }
    const bodySchema = op.requestBody?.content?.["application/json"]?.schema;
    if (bodySchema?.properties) {
      const req = new Set(bodySchema.required ?? []);
      for (const [n, s] of Object.entries(bodySchema.properties)) {
        bodyParams.push(n);
        fields.push(`${doc(s.description, "  ")}  ${key(n)}${req.has(n) ? "" : "?"}: ${ts(s, "  ")};`);
      }
    }
    const dataSchema = op.responses?.["200"]?.content?.["application/json"]?.schema?.properties?.data;
    types += `/** Parameters of \`${method.toUpperCase()} ${path}\`. */\nexport interface ${P}Params {\n${fields.join("\n")}\n}\n\n`;
    types += `/** The \`data\` object of a successful \`${method.toUpperCase()} ${path}\` response. */\nexport type ${P}Data = ${ts(dataSchema)};\n\n`;
    ops.push({
      name,
      P,
      method: method.toUpperCase(),
      path,
      tag: op.tags?.[0] ?? "Other",
      summary: op.summary ?? "",
      credits: op["x-credits"] ?? null,
      live: Boolean(op["x-live-call"]),
      scope: op["x-scope"] ?? null,
      pathParams,
      queryParams,
      bodyParams,
      paginated: queryParams.includes("cursor"),
      hasRequired: (op.parameters ?? []).some((p) => p.required) || (bodySchema?.required ?? []).length > 0,
    });
  }
}

// ---- operations.ts ----
const names = new Set();
for (const o of ops) {
  if (names.has(o.name)) throw new Error(`duplicate method name ${o.name}`);
  names.add(o.name);
}

let opsTs = header + "/* eslint-disable */\n";
opsTs += `import type {\n${ops.flatMap((o) => [`  ${o.P}Params,`, `  ${o.P}Data,`]).join("\n")}\n} from "./types.js";\n\n`;
opsTs += `/** Static description of one endpoint, used by the request builder. */
export interface OperationInfo {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  tag: string;
  summary: string;
  /** Credits one call costs, from the spec. */
  credits: number | null;
  /** True when the call reads the platform live (counts against the live limit). */
  live: boolean;
  scope: string | null;
  pathParams: readonly string[];
  queryParams: readonly string[];
  bodyParams: readonly string[];
  /** True when the endpoint takes a \`cursor\` and returns \`meta.page.next_cursor\`. */
  paginated: boolean;
}\n\n`;
opsTs += `export const operations = {\n${ops
  .map(
    (o) =>
      `  ${o.name}: { method: ${JSON.stringify(o.method)}, path: ${JSON.stringify(o.path)}, tag: ${JSON.stringify(o.tag)}, summary: ${JSON.stringify(o.summary)}, credits: ${o.credits}, live: ${o.live}, scope: ${JSON.stringify(o.scope)}, pathParams: ${JSON.stringify(o.pathParams)}, queryParams: ${JSON.stringify(o.queryParams)}, bodyParams: ${JSON.stringify(o.bodyParams)}, paginated: ${o.paginated} },`,
  )
  .join("\n")}\n} as const satisfies Record<string, OperationInfo>;\n\n`;
opsTs += `export type OperationName = keyof typeof operations;\n\n`;
opsTs += `/** Parameter and \`data\` types per operation. */\nexport interface OperationTypes {\n${ops
  .map((o) => `  ${o.name}: { params: ${o.P}Params; data: ${o.P}Data };`)
  .join("\n")}\n}\n\n`;
opsTs += `/** Operations that return \`meta.page.next_cursor\`; these work with \`client.paginate()\`. */\nexport type PaginatedOperation = ${ops
  .filter((o) => o.paginated)
  .map((o) => JSON.stringify(o.name))
  .join(" | ")};\n`;

// ---- client-methods.ts: the typed method list that HandlesApi implements ----
let methods = header + "/* eslint-disable */\n";
methods += `import type { ApiResponse, RequestOptions } from "../core.js";\nimport type { OperationTypes } from "./operations.js";\n\n`;
methods += `type Call<K extends keyof OperationTypes> = (\n  params: OperationTypes[K]["params"],\n  options?: RequestOptions,\n) => Promise<ApiResponse<OperationTypes[K]["data"]>>;\n\n`;
methods += `/** One typed method per endpoint. Implemented by \`HandlesApi\`. */\nexport interface OperationMethods {\n${ops
  .map((o) => {
    const credits = o.credits == null ? "" : ` ${o.credits} ${o.credits === 1 ? "credit" : "credits"}${o.live ? ", live read" : ""}.`;
    return `${doc(`${o.summary}.${credits} ${o.method} ${o.path}`, "  ")}  ${o.name}: Call<"${o.name}">;`;
  })
  .join("\n")}\n}\n`;

mkdirSync(outDir, { recursive: true });
writeFileSync(resolve(outDir, "types.ts"), types);
writeFileSync(resolve(outDir, "operations.ts"), opsTs);
writeFileSync(resolve(outDir, "methods.ts"), methods);
console.log(`generated ${ops.length} operations (${ops.filter((o) => o.paginated).length} paginated) from ${source}`);
